-- 102: 经费执行治理：外拨经费、外拨拨付记录、经费结转、工作量与绩效分割、结项结余处理与不可变审计
BEGIN;

-- 1. 外拨经费主表
CREATE TABLE IF NOT EXISTS "外拨经费" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "经费卡编号" bigint REFERENCES "项目经费卡"("编号") ON DELETE SET NULL,
    "合作单位名称" varchar(300) NOT NULL,
    "统一社会信用代码" varchar(50),
    "外拨合同编号" varchar(100),
    "外拨合同路径" varchar(2000),
    "外拨金额" numeric(18,2) NOT NULL,
    "已拨付金额" numeric(18,2) NOT NULL DEFAULT 0,
    "状态" varchar(30) NOT NULL DEFAULT '草稿',
    "申请人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "申请时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "审核人编号" integer REFERENCES "人员"("编号"),
    "审核时间" timestamp without time zone,
    "审核意见" varchar(1000),
    "财务凭证号" varchar(100),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_外拨经费_金额" CHECK ("外拨金额" > 0 AND "已拨付金额" >= 0 AND "已拨付金额" <= "外拨金额"),
    CONSTRAINT "ck_外拨经费_状态" CHECK ("状态" IN ('草稿','审核中','已批准','部分拨付','已拨付','已驳回','已撤回'))
);
CREATE INDEX IF NOT EXISTS "ix_外拨经费_项目" ON "外拨经费" ("流程模板编号", "项目编号", "状态");

-- 2. 外拨经费拨付记录
CREATE TABLE IF NOT EXISTS "外拨经费拨付记录" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "外拨编号" bigint NOT NULL REFERENCES "外拨经费"("编号") ON DELETE CASCADE,
    "拨付金额" numeric(18,2) NOT NULL,
    "拨付日期" date NOT NULL,
    "财务凭证号" varchar(100) NOT NULL,
    "经办人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "备注" varchar(1000),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_外拨拨付_金额" CHECK ("拨付金额" > 0),
    CONSTRAINT "uq_外拨拨付_凭证" UNIQUE ("财务凭证号")
);

-- 3. 跨年度经费结转
CREATE TABLE IF NOT EXISTS "经费结转" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "经费卡编号" bigint REFERENCES "项目经费卡"("编号") ON DELETE SET NULL,
    "结转来源年度" integer NOT NULL,
    "结转目标年度" integer NOT NULL,
    "可结转余额快照" numeric(18,2) NOT NULL,
    "结转金额" numeric(18,2) NOT NULL,
    "状态" varchar(30) NOT NULL DEFAULT '草稿',
    "申请人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "申请说明" varchar(1000),
    "审核人编号" integer REFERENCES "人员"("编号"),
    "审核时间" timestamp without time zone,
    "审核意见" varchar(1000),
    "财务凭证号" varchar(100),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_经费结转_年度" CHECK ("结转目标年度" = "结转来源年度" + 1),
    CONSTRAINT "ck_经费结转_金额" CHECK ("结转金额" > 0 AND "结转金额" <= "可结转余额快照"),
    CONSTRAINT "ck_经费结转_状态" CHECK ("状态" IN ('草稿','审核中','已结转','已驳回','已撤回'))
);
CREATE INDEX IF NOT EXISTS "ix_经费结转_项目" ON "经费结转" ("流程模板编号", "项目编号", "结转来源年度");

-- 4. 经费分割方案 (工作量与项目绩效)
CREATE TABLE IF NOT EXISTS "经费分割方案" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "分割类型" varchar(30) NOT NULL,
    "基数金额" numeric(18,2) NOT NULL,
    "期间或年度" varchar(50) NOT NULL,
    "状态" varchar(30) NOT NULL DEFAULT '草稿',
    "制定人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "确认人编号" integer REFERENCES "人员"("编号"),
    "确认时间" timestamp without time zone,
    "备注" varchar(1000),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_经费分割_类型" CHECK ("分割类型" IN ('工作量分割','绩效分割')),
    CONSTRAINT "ck_经费分割_基数" CHECK ("基数金额" > 0),
    CONSTRAINT "ck_经费分割_状态" CHECK ("状态" IN ('草稿','已提交','已确认','已作废'))
);

-- 5. 经费分割明细
CREATE TABLE IF NOT EXISTS "经费分割明细" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "方案编号" bigint NOT NULL REFERENCES "经费分割方案"("编号") ON DELETE CASCADE,
    "人员编号" integer NOT NULL REFERENCES "人员"("编号"),
    "部门名称" varchar(100),
    "分割比例" numeric(5,2) NOT NULL,
    "分割金额" numeric(18,2) NOT NULL,
    "分配说明" varchar(500),
    CONSTRAINT "uq_经费分割明细_方案人员" UNIQUE ("方案编号", "人员编号"),
    CONSTRAINT "ck_经费分割明细_比例" CHECK ("分割比例" >= 0 AND "分割比例" <= 100),
    CONSTRAINT "ck_经费分割明细_金额" CHECK ("分割金额" >= 0)
);

-- 6. 结项结余处理
CREATE TABLE IF NOT EXISTS "结项结余处理" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "结余金额快照" numeric(18,2) NOT NULL,
    "处理方式" varchar(50) NOT NULL,
    "后续流程模板编号" integer,
    "后续项目编号" integer,
    "处理说明" varchar(1000),
    "状态" varchar(30) NOT NULL DEFAULT '草稿',
    "经办人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "审核人编号" integer REFERENCES "人员"("编号"),
    "审核时间" timestamp without time zone,
    "财务凭证号" varchar(100),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_结余处理_金额" CHECK ("结余金额快照" >= 0),
    CONSTRAINT "ck_结余处理_方式" CHECK ("处理方式" IN ('按规定上缴','留归单位统筹','结转后续项目','退回资助方')),
    CONSTRAINT "ck_结余处理_状态" CHECK ("状态" IN ('草稿','审核中','已完成','已驳回','已撤回'))
);

-- 7. 经费执行不可变审计日志
CREATE TABLE IF NOT EXISTS "经费执行审计" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "业务类型" varchar(50) NOT NULL,
    "业务主键" bigint NOT NULL,
    "操作动作" varchar(50) NOT NULL,
    "变动前状态" varchar(50),
    "变动后状态" varchar(50),
    "操作人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "详细快照" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "记录时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "ix_经费执行审计_业务" ON "经费执行审计" ("业务类型", "业务主键", "记录时间" DESC);

-- 审计表防篡改触发器
CREATE OR REPLACE FUNCTION "fn_经费执行审计_防篡改"()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '经费执行审计记录不可修改或删除';
END;
$$;

DROP TRIGGER IF EXISTS "trg_经费执行审计_只追加" ON "经费执行审计";
CREATE TRIGGER "trg_经费执行审计_只追加"
BEFORE UPDATE OR DELETE ON "经费执行审计"
FOR EACH ROW EXECUTE FUNCTION "fn_经费执行审计_防篡改"();

-- 权限配置
INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "备注")
VALUES (214, 2, '经费执行治理', '科研办公/科研办公/经费执行治理.html', TRUE, '外拨经费、跨年结转、工作量与绩效分割及结项结余处理')
ON CONFLICT ("编号") DO UPDATE SET "名称"=EXCLUDED."名称", "路径"=EXCLUDED."路径", "备注"=EXCLUDED."备注";

INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", 214 FROM "角色" r
WHERE r."名称" IN ('系统管理员','科研管理员','科技办','财务管理员','财务')
  AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=214);

UPDATE "系统迁移版本"
SET "版本"=102, "脚本"='102_fund_execution_extensions.sql',
    "检查摘要"='增加外拨经费、跨年结转、工作量与绩效分割、结项结余及执行审计', "应用时间"=CURRENT_TIMESTAMP
WHERE "编号"=1;

COMMIT;
